test('totals spend by category', () => {
  const report = buildReport(parseCsv(SAMPLE));
  assert.strictEqual(report.byCategory.groceries, 10);
  assert.strictEqual(report.byCategory.transport, 2.5);
  assert.strictEqual(report.net, 12.5);
});

test('refunds subtract from net spend', () => {
  const csv = [
    'date,category,description,amount',
    '2026-02-01,groceries,Market,10.00',
    '2026-02-03,refund,Returned item,4.00',
  ].join('\n');
  const report = buildReport(parseCsv(csv));
  assert.strictEqual(report.byCategory.refund, -4);
  assert.strictEqual(report.net, 6);
});

// Guard: a category with no declared direction used to default to +1 silently, which is
// how refunds got counted as spend. Adding a category without a direction must fail loudly.
test('every category the pipeline can produce has a declared direction', () => {
  for (const category of [...KNOWN_CATEGORIES, 'other']) {
    assert.doesNotThrow(
      () => signedAmount({ category, amount: 1 }),
      `category "${category}" has no declared direction`
    );
  }
});

test('an undeclared direction throws instead of defaulting to spend', () => {
  assert.throws(
    () => signedAmount({ category: '__no_such_category__', amount: 1, __bypass: true }),
    /no direction declared/
  );
});

// Regression: these exact rows reconcile to 180.90 on the bank statement.
test('the shipped export reconciles with the bank statement', () => {
  const file = path.join(__dirname, '..', 'data', 'transactions.csv');
  const report = buildReport(parseCsv(fs.readFileSync(file, 'utf8')));
  assert.strictEqual(report.byCategory.refund, -218.65);
  assert.strictEqual(report.net, 180.9);
});

